// Minimal expect() bridge from bun:test to node:assert — only the matchers
// used by the ported suites, so the ported test files stay close to upstream.
// `not` is generated by inverting each positive matcher (assertion must throw).
import assert from "node:assert/strict"

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value)
}

function subsetMatches(actual: unknown, expected: unknown): boolean {
  if (isPlainObject(expected) && isPlainObject(actual)) {
    return Object.keys(expected).every(
      (key) => key in actual && subsetMatches(actual[key], expected[key]),
    )
  }
  if (Array.isArray(expected) && Array.isArray(actual)) {
    return (
      expected.length <= actual.length &&
      expected.every((value, i) => subsetMatches(actual[i], value))
    )
  }
  return Object.is(actual, expected)
}

function checkThrownError(error: unknown, expected: unknown): void {
  if (expected === undefined) return
  const message = error instanceof Error ? error.message : String(error)
  if (expected instanceof RegExp) {
    assert.ok(expected.test(message), `expected "${message}" to match ${expected}`)
  } else {
    assert.ok(
      message.includes(String(expected)),
      `expected "${message}" to include "${String(expected)}"`,
    )
  }
}

const positive = {
  toBe: (actual: unknown, expected: unknown) => assert.strictEqual(actual, expected),
  toEqual: (actual: unknown, expected: unknown) => assert.deepStrictEqual(actual, expected),
  toContain: (actual: unknown, expected: unknown) => {
    if (typeof actual === "string") {
      assert.ok(actual.includes(String(expected)), `expected "${actual}" to contain "${expected}"`)
    } else if (Array.isArray(actual)) {
      assert.ok(actual.includes(expected), `expected array to contain ${JSON.stringify(expected)}`)
    } else {
      throw new TypeError("toContain expects a string or array")
    }
  },
  toMatch: (actual: unknown, expected: RegExp) => {
    if (typeof actual !== "string") throw new TypeError("toMatch expects a string")
    assert.ok(expected.test(actual), `expected "${actual}" to match ${expected}`)
  },
  toBeNull: (actual: unknown) => assert.strictEqual(actual, null),
  toBeUndefined: (actual: unknown) => assert.strictEqual(actual, undefined),
  toBeDefined: (actual: unknown) => assert.notStrictEqual(actual, undefined),
  toBeTruthy: (actual: unknown) => assert.ok(actual, `expected ${JSON.stringify(actual)} to be truthy`),
  toBeFalsy: (actual: unknown) => assert.ok(!actual, `expected ${JSON.stringify(actual)} to be falsy`),
  toBeGreaterThan: (actual: unknown, expected: number) => assert.ok((actual as number) > expected),
  toBeGreaterThanOrEqual: (actual: unknown, expected: number) => assert.ok((actual as number) >= expected),
  toBeLessThan: (actual: unknown, expected: number) => assert.ok((actual as number) < expected),
  toBeLessThanOrEqual: (actual: unknown, expected: number) => assert.ok((actual as number) <= expected),
  toHaveLength: (actual: unknown, expected: number) =>
    assert.ok((actual as { length: number }).length === expected, `expected length ${expected}`),
  toEndWith: (actual: unknown, expected: string) => {
    assert.ok(String(actual).endsWith(expected), `expected "${String(actual)}" to end with "${expected}"`)
  },
  toMatchObject: (actual: unknown, expected: unknown) => {
    assert.ok(subsetMatches(actual, expected), `expected ${JSON.stringify(actual)} to match object ${JSON.stringify(expected)}`)
  },
}

type Matcher = (...args: unknown[]) => void

const invert = (fn: Matcher): Matcher => (...args: unknown[]) => {
  try {
    fn(...args)
  } catch (error) {
    if (error instanceof assert.AssertionError) return // positive failed, negated passes
    throw error // wrong-typed actual is a bug, not a pass
  }
  assert.fail("expected the negated matcher to fail")
}

const negated = Object.fromEntries(
  Object.entries(positive).map(([name, fn]) => [name, invert(fn as Matcher)]),
)

export interface Matchers {
  toBe(expected: unknown): void
  toEqual(expected: unknown): void
  toContain(expected: unknown): void
  toMatch(expected: RegExp): void
  toBeNull(): void
  toBeUndefined(): void
  toBeDefined(): void
  toBeTruthy(): void
  toBeFalsy(): void
  toBeGreaterThan(expected: number): void
  toBeGreaterThanOrEqual(expected: number): void
  toBeLessThan(expected: number): void
  toBeLessThanOrEqual(expected: number): void
  toHaveLength(expected: number): void
  toEndWith(expected: string): void
  toMatchObject(expected: unknown): void
}

export interface Expectation extends Matchers {
  not: Matchers
  toThrow(expected?: unknown): void
  rejects: { toThrow(expected?: unknown): Promise<void> }
  resolves: { toEqual(expected: unknown): Promise<void>; toBe(expected: unknown): Promise<void> }
}

const bind = (map: Record<string, Matcher>, actual: unknown): Matchers =>
  Object.fromEntries(
    Object.entries(map).map(([name, fn]) => [name, (...args: unknown[]) => fn(actual, ...args)]),
  ) as unknown as Matchers

export function expect(actual: unknown): Expectation {
  return {
    not: bind(negated, actual),
    ...bind(positive, actual),
    toThrow: (expected?: unknown) => {
      const fn = actual as () => unknown
      assert.strictEqual(typeof fn, "function", "toThrow expects a function")
      try {
        fn()
      } catch (error) {
        checkThrownError(error, expected)
        return
      }
      assert.fail("expected function to throw")
    },
    get rejects() {
      return {
        toThrow: async (expected?: unknown) => {
          try {
            await actual
          } catch (error) {
            checkThrownError(error, expected)
            return
          }
          assert.fail("expected promise to reject")
        },
      }
    },
    get resolves() {
      return {
        toEqual: async (expected: unknown) => assert.deepStrictEqual(await actual, expected),
        toBe: async (expected: unknown) => assert.strictEqual(await actual, expected),
      }
    },
  } as Expectation
}
